package lk.repairdesk.api.controller; import jakarta.validation.Valid; import lk.repairdesk.api.dto.DeviceDtos.*; import lk.repairdesk.api.service.DeviceService; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/devices") public class DeviceController {private final DeviceService s;public DeviceController(DeviceService s){this.s=s;}@PostMapping ResponseEntity<Response> create(@Valid @RequestBody Request r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));}@GetMapping Page<Response> mine(@PageableDefault(size=10,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return s.mine(p);}}